const SB_KEY = 'spmod.sandbox';
const TEST_KEY = 'spmod.test';

/**
 * 记下测试页填过的数，**带上这一局的 matchId**。维护者的口径是「一局的测试就是一局的」：
 * 换了一局（matchId 变了）这份记忆就作废（见 `loadTestPrefs()` 与 `drawTestPage()` 的复位）。
 */
function saveTestPrefs() {
  try {
    const mid = store.get()?.match?.public?.matchId ?? null;
    localStorage.setItem(TEST_KEY, JSON.stringify({ matchId: mid, funds: local.test.funds, round: local.test.round, roundCap: local.test.roundCap, shopLevel: local.test.shopLevel, enemies: local.test.enemies, wave: local.test.wave, all: local.test.all, map: local.test.map, mapAll: local.test.mapAll, bondId: local.test.bondId, bondLayers: local.test.bondLayers, bondAll: local.test.bondAll, comboRound: local.test.comboRound, comboPick: local.test.comboPick, comboAll: local.test.comboAll }));
  } catch { /* 存不下就算了，下次回默认值 */ }
}

/**
 * 读回测试页填过的数，**只认同一局存下的**：`matchId` 对不上（换了一局）就整份丢掉 —— 上一局调过的
 * 资金/回合/上限/敌人/地图/盟约不会带到这一局来。填过的数不合法就用默认值，不让坏数据进面板。
 */
function loadTestPrefs() {
  try {
    const raw = localStorage.getItem(TEST_KEY);
    if (!raw) return;
    const s = JSON.parse(raw) || {};
    const mid = store.get()?.match?.public?.matchId ?? null;
    if (!s.matchId || !mid || s.matchId !== mid) return;
    testMatchScope = mid;
    if (Number.isInteger(s.funds) && s.funds >= 0 && s.funds <= 99999) local.test.funds = s.funds;
    if (Number.isInteger(s.round) && s.round >= 1 && s.round <= 99) local.test.round = s.round;
    if (Number.isInteger(s.roundCap) && s.roundCap >= 1 && s.roundCap <= 99) local.test.roundCap = s.roundCap;
    if (Number.isInteger(s.shopLevel) && s.shopLevel >= 1 && s.shopLevel <= 6) local.test.shopLevel = s.shopLevel;
    if (Array.isArray(s.enemies)) {
      local.test.enemies = s.enemies.filter((e) => !!e && typeof e.key === 'string' && e.key
        && Number.isInteger(e.count) && e.count >= 1 && e.count <= 50).slice(0, 64);
    }
    if (typeof s.wave === 'string' && s.wave) local.test.wave = s.wave;
    if (typeof s.all === 'boolean') local.test.all = s.all;
    if (typeof s.map === 'string' && s.map) local.test.map = s.map;
    if (typeof s.mapAll === 'boolean') local.test.mapAll = s.mapAll;
    if (typeof s.bondId === 'string' && s.bondId) local.test.bondId = s.bondId;
    if (Number.isInteger(s.bondLayers) && s.bondLayers >= 0 && s.bondLayers <= 999) local.test.bondLayers = s.bondLayers;
    if (typeof s.bondAll === 'boolean') local.test.bondAll = s.bondAll;
    if (typeof s.comboPick === 'string') local.test.comboPick = s.comboPick;
    if (Number.isInteger(s.comboRound) && s.comboRound >= 1 && s.comboRound <= 99) local.test.comboRound = s.comboRound;
    if (typeof s.comboAll === 'boolean') local.test.comboAll = s.comboAll;
  } catch { /* 坏了就用默认值 */ }
}

