/**
 * 测试页。每个控件都是「填一个数 → 发一条意图」，服务端照游戏自己的账本改，本机只记你填过的数。
 *
 * 三条规矩（跟沙盒条上的「设置调度」一致）：
 *   1. **总开关关着就不发**，只在 console 里说一句 —— 不发比发了被拒更好查。
 *   2. 填进去的值先夹到合法区间再存本机记忆，免得面板回显一个服务端根本没接受的数。
 *   3. 服务端的真实值以它回的 view 为准（`v.priv.modSandbox.test.*`），不是我们记的那个。
 *   4. ⚠️ 面板拿到的 `v` 是**包装对** { priv, pub, pick, shop, slots }，服务端挂的 mod* 字段都在 `v.priv` 上。
 *      写成 `v.modSandbox` 会抛 TypeError（read of undefined）并把**整页**画不出来（实测 drawTestPage）。
 */
function testRow(title, hint, input, button) {
  return el('div', { class: 'spmod-sbrow' },
    el('span', { class: 'spmod-sbtitle', title: hint }, title),
    input, button,
  );
}

/** 一个「填数字 + 按一下」的方块。夹取、记忆、发送三件事都在这里，三个功能共用。 */
function testNumber({ key, value, min, max, width = 4.2, label, hint, send, reset = null, placeholder = '' }) {
  const box = el('input', {
    type: 'number', min, max, step: 1, value: String(value), class: 'spmod-sbnum',
    style: `width:${width}em`,
    ...(placeholder ? { placeholder: String(placeholder) } : {}),
    onChange: (e) => {
      const n = Number(e.currentTarget.value);
      if (Number.isInteger(n)) { local.test[key] = Math.max(min, Math.min(max, n)); saveTestPrefs(); }
    },
  });
  const btns = [el('button', {
    class: 'spmod-sbbtn', type: 'button', title: hint,
    onClick: () => send(Math.max(min, Math.min(max, Number(box.value) || min))),
  }, '设置')];
  if (reset) btns.push(el('button', {
    class: 'spmod-sbbtn', type: 'button', title: '清掉这一项的改动，回到数据表/游戏的默认值（框里也会跳回默认值）',
    onClick: () => {
      const d = Number(placeholder);
      const hasNum = Number.isFinite(d) && d > 0;
      box.value = hasNum ? String(d) : '';
      local.test[key] = hasNum ? d : '';
      saveTestPrefs();
      reset();
      render(true);
    },
  }, '重置'));
  return testRow(label, hint, el('span', { class: 'spmod-sbrow' }, box, ...btns), null);
}

function sendTestFunds(n) {
  if (!enableOn('testFunds')) { console.info('[luck] testFunds is off in the master switch'); return; }
  net.request(TESTFUNDS, { funds: n })
