// 时限：两个字段一起发（消息里字段不能省），另一条取**服务端回显里「上次设过的值」**，
// 这样设一条不会把另一条冲掉。`null` = 恢复游戏原本的值。
function testWantTimer() {
  const s = store.get() || {};
  const t = s.match && s.match.private && s.match.private.modSandbox ? s.match.private.modSandbox.test : null;
  const w = t && t.timer && t.timer.want ? t.timer.want : {};
  return { combat: Number.isInteger(w.combat) ? w.combat : null, prep: Number.isInteger(w.prep) ? w.prep : null };
}

function sendTestTimerCombat(n) {
  if (!enableOn('testEnemy')) { console.info('[luck] test timer is off in the master switch'); return; }
  const v = Number.isInteger(n) && n >= 1 ? n : null;
  const w = testWantTimer();
  net.request(TESTTIMER, { combat: v, prep: w.prep })
    .then(() => console.info(`[luck] combat time limit -> ${v === null ? 'data' : v}`))
    .catch((e) => console.warn('[luck] combat time limit refused', errText(e)));
}

function sendTestTimerPrep(n) {
  if (!enableOn('testEnemy')) { console.info('[luck] test timer is off in the master switch'); return; }
  const v = Number.isInteger(n) && n >= 1 ? n : null;
  net.request(TESTTIMER, { prep: v, combat: testWantTimer().combat })
    .then(() => console.info(`[luck] prep timer -> ${v === null ? 'data' : v}`))
    .catch((e) => console.warn('[luck] prep timer refused', errText(e)));
}

