/** 「设置敌人」那一块：整份换成某个波次模板，或者自己挑一份名单（怪 + 数量）。
 *  选怪的下拉默认只列「波次里真出过的」怪 —— 就是维护者说的「其他波次可能出的怪」；
 *  勾上「列出全部敌人」就放开到整张 data/enemies.json。 */
function testEnemySection(v) {
  const t = (v && v.priv && v.priv.modSandbox && v.priv.modSandbox.test) || null;
  const table = data.get('enemies') || {};
  const nameOf = (k) => {
    const r = table[k];
    const n = r && (r.name || r.appellation);
    return typeof n === 'string' && n ? n : String(k);
  };
  // 「自选敌人」的四类候选（维护者 m03492）：常规 / 特训 / 赏金 / boss。
  const waveKeys = new Set();
  for (const w of WAVE_TEMPLATES) {
    for (const s of ((w && w.spawns) || [])) {
      const k = s && (s.key != null ? s.key : s.enemyKey);
      if (k != null) waveKeys.add(String(k));
    }
  }
  const specKeys = new Set();
  {
    const fac = data.get('factions') || {};
    for (const [tid, ty] of Object.entries(fac.types || {})) {
      if (tid === 'SPECIAL' || !ty || typeof ty !== 'object') continue;
      for (const k of (Array.isArray(ty.pool) ? ty.pool : [])) specKeys.add(String(k));
    }
    for (const e of Object.values(fac.entries || {})) {
      if (!e || e.type === 'SPECIAL') continue;
      for (const k of [...(e.N || []), ...(e.E || [])]) {
        const kk = k && typeof k === 'object' ? k.key : k;
        if (typeof kk === 'string' && kk) specKeys.add(kk);
      }
    }
  }
  const bountyCoin = new Map();
  {
    const seen = new Set();
    const walk = (node, depth) => {
      if (!node || typeof node !== 'object' || depth > 6 || seen.has(node)) return;
      seen.add(node);
      if (typeof node.enemyKey === 'string' && node.enemyKey) {
        const coin = Number(node.coin) || 0;
        bountyCoin.set(node.enemyKey, Math.max(bountyCoin.get(node.enemyKey) || 0, coin));
      }
      for (const child of Object.values(node)) walk(child, depth + 1);
    };
    walk(data.get('choices') || {}, 0);
  }
  const bossKeys = new Set(Object.values(data.get('bosses') || {}).map((b) => b && b.enemyKey).filter((k) => typeof k === 'string'));
  const inTable = (k) => Object.prototype.hasOwnProperty.call(table, k);
  const shown = (list) => list.filter((k) => inTable(k)).sort((a, b) => nameOf(a).localeCompare(nameOf(b), 'zh'));
  const groups = [
    ['常规敌人', shown([...waveKeys].filter((k) => !specKeys.has(k) && !bossKeys.has(k)))],
    ['特训敌人', shown([...specKeys].filter((k) => !bossKeys.has(k)))],
    ['赏金敌人', shown([...bountyCoin.keys()])],
    ['boss 敌人', shown([...bossKeys])],
  ];
  if (local.test.all) {
    const used = new Set(groups.flatMap(([, list]) => list));
    groups.push(['其它敌人', shown(Object.keys(table).filter((k) => !used.has(k)))]);
  }
  const optOf = (k) => el('option', { value: k }, bountyCoin.has(k) ? nameOf(k) + '（赏金 ' + (bountyCoin.get(k) || '?') + '）' : nameOf(k));

  const box = el('div', { class: 'spmod-sbsection' },
    el('div', { class: 'spmod-sbtitle' }, '设置敌人'),
    el('div', { class: 'spmod-sbhint' },
      '把这一回合的怪换掉。现在服务端记的是：' + enemyNowText(t)
      + '（从下一回合开始生效；已经开打的那一回合不受影响）。'),
  );

  const sel = el('select', { class: 'spmod-sbnum', style: 'width:14em' },
    ...(groups.some(([, list]) => list.length)
      ? groups.flatMap(([label, list]) => (list.length
        ? [el('optgroup', { label }, ...list.map(optOf))]
        : []))
      : [el('option', { value: '' }, '（敌人表还没载入）')]));
  const cnt = el('input', { type: 'number', min: 1, max: 50, step: 1, value: '1', class: 'spmod-sbnum', style: 'width:4.2em' });
  const listBox = el('div', { class: 'spmod-sbrow' });
  const redraw = () => {
    listBox.textContent = '';
    if (!local.test.enemies.length) {
      listBox.append(el('span', { class: 'spmod-hint' }, '（名单是空的 —— 不挑就是游戏的原始波次）'));
      return;
    }
    local.test.enemies.forEach((e, i) => {
      listBox.append(el('span', { class: 'spmod-hint' }, nameOf(e.key) + ' × ' + e.count + ' ',
        el('button', { class: 'spmod-sbbtn', type: 'button', title: '去掉这一条', onClick: () => { local.test.enemies.splice(i, 1); saveTestPrefs(); redraw(); } }, '×')));
    });
  };
  redraw();
  const all = el('input', { type: 'checkbox', title: '放开到整张 data/enemies.json（默认只列波次里真出过的怪）' });
  if (local.test.all) all.setAttribute('checked', '');
  all.addEventListener('change', (e) => { local.test.all = !!e.currentTarget.checked; saveTestPrefs(); });

  box.append(testRow('自选敌人', '选一只怪 + 数量，按「加入」放进名单；一只怪可以加多条。按类别分好：常规敌人 / 特训敌人 / 赏金敌人（括号里是赏金）/ boss 敌人。',
    el('span', { class: 'spmod-sbrow' }, sel, cnt,
      el('button', { class: 'spmod-sbbtn', type: 'button', title: '把选中的怪按这个数量加进名单', onClick: () => {
        const k = sel.value; if (!k) return;
        const c = Math.max(1, Math.min(50, Number(cnt.value) || 1));
        const hit = local.test.enemies.find((e) => e.key === k);
        if (hit) hit.count = Math.max(1, Math.min(50, hit.count + c));
        else local.test.enemies.push({ key: k, count: c });
        saveTestPrefs(); redraw();
      } }, '加入')),
    el('label', { class: 'spmod-enablerow', title: '默认只列「波次里真出过的怪」—— 就是其他波次可能出的那些' }, all,
      el('span', { class: 'spmod-enablelabel' }, '列出全部敌人'))));

  box.append(testRow('名单', '发给服务端。空名单 + 不用模板 = 恢复游戏原本的怪。',
    listBox,
    el('span', { class: 'spmod-sbrow' },
      el('button', { class: 'spmod-sbbtn', type: 'button', title: '把这份名单发给服务端', onClick: () => sendTestEnemy() }, '应用名单'),
      el('button', { class: 'spmod-sbbtn', type: 'button', title: '模板与名单都清空，回到游戏原本的波次', onClick: () => { local.test.enemies = []; local.test.wave = null; saveTestPrefs(); sendTestEnemy(); } }, '恢复原样'))));

  // ── 自选 boss（owner 的口径）：跳去 boss 回合并指定打哪一只；8/9/10 是隐匿核心那三只。 ──────────
  const bossTable = Object.values(data.get('bosses') || {}).sort((a, b) => (a.sortId || 0) - (b.sortId || 0));
  const bossLabel = (b) => (b.name || b.bossId) + (b.hidden ? '（隐匿核心）' : '') + ' · ' + b.bossId;
  const bossGroup = (hidden) => bossTable.filter((b) => !!b.hidden === hidden);
  const bossSel = el('select', { class: 'spmod-sbnum', style: 'width:19em' },
    ...(bossTable.length
      ? [
        ...(bossGroup(false).length ? [el('optgroup', { label: 'boss 回合' }, ...bossGroup(false).map((b) => el('option', { value: b.bossId }, bossLabel(b))))] : []),
        ...(bossGroup(true).length ? [el('optgroup', { label: '隐匿核心（第 ' + (v && v.pub && v.pub.hiddenRound != null ? v.pub.hiddenRound : '?') + ' 回合）' }, ...bossGroup(true).map((b) => el('option', { value: b.bossId }, bossLabel(b))))] : []),
      ]
      : [el('option', { value: '' }, '（boss 表还没载入）')]));
  box.append(testRow('自选boss',
    '跳到 boss 回合，并把这一局要打的那只 boss 换成上面这只（走游戏自己的开回合流程）。',
    bossSel,
    el('button', { class: 'spmod-sbbtn', type: 'button', title: '跳去 boss 回合，并指定打这一只 boss', onClick: () => sendTestBoss(bossSel.value) }, '打这只 boss')));
  box.append(el('div', { class: 'spmod-sbhint' },
    '提示：选中一只 boss 之后想换别的 boss，要先把回合切到别的回合再切回来；如果不想让这一局就此结束，记得把「回合上限」调到这个 boss 回合之后。'));

  return box;
}

/** 出怪组合那一行的一条：概率 + 这一套的具体怪 + 有没有对不上的组。 */
function comboOption(c) {
  const pct = (Number(c.p) || 0) * 100;
  const txt = pct >= 1 ? pct.toFixed(0) + '%' : pct >= 0.1 ? pct.toFixed(1) + '%' : pct.toFixed(2) + '%';
  const bits = [(c.current ? '★ ' : '') + txt, (c.bossName ? c.bossName + '：' : '') + (c.label || '（一组怪都不出）')];
  if (c.dropped) bits.push('-' + c.dropped + ' 组对不上');
  if (c.fallback) bits.push('SPECIAL 回退');
  return bits.join('  ');
}

/** 向服务端要「第几回合、要不要全部 boss」的组合；视图里已经是想要的那一份就什么都不做。
 *  （这个函数在 render 里被调用，所以必须能安全地重复调用 —— 否则会自己把自己转成死循环。） */
let combosAsked = { round: null, all: null, at: 0 };
function requestCombos(round, all, force = false) {
  if (!enableOn('testEnemy')) return;
  const want = !!all;
  const v0 = view();
  const tt0 = (v0 && v0.priv && v0.priv.modSandbox && v0.priv.modSandbox.test) || null;
  const have = tt0 && tt0.combos && tt0.combos.round === round && !!tt0.combos.all === want;
  if (have && !force) return;
  const now = Date.now();
  if (!force && combosAsked.round === round && combosAsked.all === want && now - combosAsked.at < 2000) return;
  combosAsked = { round, all: want, at: now };
  net.request(TESTCOMBOS, { round, all: want })
    .then(() => console.info('[luck] combos -> round ' + round + (want ? ' (all bosses)' : '')))
    .catch((e) => console.warn('[luck] combos refused', errText(e)));
}

/** 把选中的那一种组合整份换上（走已有的「设置敌人」通道：名单 = 那一种组合的具体怪 + 数量）。 */
function applyCombo() {
  if (!enableOn('testEnemy')) { console.info('[luck] testEnemy is off in the master switch'); return; }
  const v = view();
  const tt = (v && v.priv && v.priv.modSandbox && v.priv.modSandbox.test) || null;
  const list = tt && tt.combos && Array.isArray(tt.combos.combos) ? tt.combos.combos : [];
  const pick = list.find((c) => c.id === local.test.comboPick) || list.find((c) => c.current) || list[0] || null;
  if (!pick || !Array.isArray(pick.rows) || !pick.rows.length) { console.info('[luck] combo: nothing to apply'); return; }
  local.test.enemies = pick.rows.map((r) => ({ key: r.key, count: r.count }));
  local.test.wave = null;
  local.test.comboPick = pick.id;
  saveTestPrefs();
  sendTestEnemy();
}

/** 服务端现在记着的敌人设置，翻成一句人话。
 *  形状必须跟 L4 的 `L4-view` 回显**逐字对齐** —— 那边发的是 `enemy: { list, wave }`
 *  （`list` 是 `[{key,count}]`），不是两个平铺的字段。字段名对不上时这里会静默显示
 *  「游戏的原始波次」，看起来像功能没生效，其实只是面板读错了地方。 */
function enemyNowText(t) {
  if (!t || !t.enemy) return '游戏的原始波次';
  const bits = [];
  const list = Array.isArray(t.enemy.list) ? t.enemy.list : [];
  if (t.enemy.wave) bits.push('模板 ' + t.enemy.wave);
  if (list.length) bits.push('自己挑的 ' + list.length + ' 种（共 ' + list.reduce((n, e) => n + (Number(e && e.count) || 0), 0) + ' 只）');
  return bits.length ? bits.join(' + ') : '游戏的原始波次';
}

/** 把当前的模板 + 名单发给服务端。两个都空就是「恢复原样」。 */
function sendTestEnemy() {
  if (!enableOn('testEnemy')) { console.info('[luck] testEnemy is off in the master switch'); return; }
  const list = local.test.enemies.map((e) => ({ key: e.key, count: e.count }));
  const wave = local.test.wave || null;
  net.request(TESTENEMY, wave ? { wave, list } : { list })
    .then(() => console.info('[luck] test enemies -> ' + (wave ? 'template ' + wave : 'no template') + ', ' + list.length + ' picks'))
    .catch((e) => console.warn('[luck] test enemies refused', errText(e)));
}

/** 「更换地图」那一块：把这一局的地图换成你选的这张。 */
// 候选默认取服务端 view 给的 `maps`（本模式会抽的池子）；勾上「列出全部地图」放开到本机那份 data/stages.json。
function testMapSection(v) {
  const t = (v && v.priv && v.priv.modSandbox && v.priv.modSandbox.test) || null;
  const stageOf = (id) => { try { return data.lookup('stages', id) || null; } catch { return null; } };
  const nameOf = (id) => {
    const r = stageOf(id);
    const n = r && (r.name || r.id);
    return typeof n === 'string' && n ? n : String(id);
  };
  const pool = Array.isArray(t && t.maps) ? t.maps : [];
  const nowId = (t && typeof t.map === 'string' ? t.map : '') || (v && v.pub && v.pub.stageId) || '';
  const ids = local.test.mapAll
    ? (data.list('stages') || []).map((st) => st && (st.id || st.key || st.stageId)).filter((id) => typeof id === 'string' && id).sort((a, b) => nameOf(a).localeCompare(nameOf(b), 'zh'))
    : pool.map((m) => m && m.id).filter((id) => typeof id === 'string');
  const box = el('div', { class: 'spmod-sbsection' },
    el('div', { class: 'spmod-sbtitle' }, '更换地图'),
    el('div', { class: 'spmod-sbhint' },
      '这一局现在是：' + (nowId ? nameOf(nowId) : '?'),
      '（换完立刻生效：布置图与地图装饰跟着换；这一回合的怪不变）'),
  );
  const sel = el('select', { class: 'spmod-sbnum', style: 'width:17em' },
    ...(ids.length ? ids.map((id) => el('option', { value: id }, nameOf(id) + ' · ' + id)) : [el('option', { value: '' }, '（地图表还没载入）')]));
  if (local.test.map && ids.includes(local.test.map)) sel.value = local.test.map;
  else if (nowId && ids.includes(nowId)) sel.value = nowId;
  sel.addEventListener('change', (e) => { local.test.map = e.currentTarget.value || null; saveTestPrefs(); });
  const all = el('input', { type: 'checkbox', title: '放开到本机那份 data/stages.json 的全部地图（默认只列本模式会抽的池子）' });
  if (local.test.mapAll) all.setAttribute('checked', '');
  all.addEventListener('change', (e) => { local.test.mapAll = !!e.currentTarget.checked; saveTestPrefs(); render(true); });
  box.append(testRow('换成', '把这一局的地图换成上面这张。服务端改的是 match.stageId / match.stage，布置图当场重算。', sel,
    el('button', { class: 'spmod-sbbtn', type: 'button', title: '把这一局的地图换成上面这张', onClick: () => sendTestMap() }, '应用')));
  box.append(el('div', { class: 'spmod-sbrow' },
    el('label', { class: 'spmod-enablerow', title: '默认只列这个模式会抽的图' }, all,
      el('span', { class: 'spmod-enablelabel' }, '列出全部地图'))));
  return box;
}

