/**
 * 「设置盟约层数」那一块：选一个盟约 + 填一个层数 + 设置。
 * 默认就列**全部**盟约（按现在有几层标出来），不再有「列出全部盟约」开关。
 * 回显两条：选中那个盟约**现在**的真实层数（读 `v.priv.bonds`）与服务端记的「上次设过多少」（`t.bond`）。
 */
function testBondSection(v) {
  const t = (v && v.priv && v.priv.modSandbox && v.priv.modSandbox.test) || null;
  const priv = (v && v.priv) || null;
  const bonds = (priv && priv.bonds) || {};
  const box = el('div', { class: 'spmod-sbsection' }, el('div', { class: 'spmod-sbtitle' }, '设置盟约层数'));
  const idOf = (b) => (b && (b.bondId || b.id)) || null;
  const mine = Object.keys(bonds);
  const allIds = (data.list('bonds') || []).map(idOf).filter(Boolean);
  const ids = allIds.length ? allIds : mine;
  const nameOf = (id) => { const rec = data.lookup('bonds', id); return (rec && rec.name) || id; };
  const pick = ids.includes(local.test.bondId) ? local.test.bondId : (ids[0] || '');
  const label = (id) => { const b = bonds[id]; return nameOf(id) + (b ? '（' + (b.layers || 0) + ' 层' + (b.active ? '·已激活' : '') + '）' : ''); };
  const sel = el('select', { class: 'spmod-sbnum', style: 'width:16em' },
    ...(ids.length ? ids.map((id) => el('option', { value: id }, label(id))) : [el('option', { value: '' }, '（盟约表还没载入）')]));
  if (pick) sel.value = pick;
  sel.addEventListener('change', (e) => { local.test.bondId = e.currentTarget.value || ''; saveTestPrefs(); render(true); });
  const input = el('input', { type: 'number', min: 0, max: 999, step: 1, value: String(local.test.bondLayers), class: 'spmod-sbnum', style: 'width:4.2em' });
  input.addEventListener('change', (e) => { const n = Number(e.currentTarget.value); if (Number.isInteger(n)) { local.test.bondLayers = Math.max(0, Math.min(999, n)); saveTestPrefs(); } });
  box.append(testRow('层数', '把上面那个盟约设成这个层数（0–999）：涨层走游戏自己的加层（PREP 里会播报），降层直接改存储再重算激活。', input,
    el('button', { class: 'spmod-sbbtn', type: 'button', title: '把这个盟约的层数设成左边的数', onClick: () => sendTestBond(pick) }, '设置')));
  box.append(testRow('盟约', '全部盟约都列在这里（名字后面括号里是它现在有几层）。', sel, null));
  return box;
}

